        // hero-guide.js 英雄引導訊息
        heroGreeting0: '嗨，第一次見面。這條海岸線很長，你不需要一次走完，只要願意踏出第一步，我會一路在這裡陪你。從蜜月灣開始，我們慢慢試著聽見自己。',
        heroGreeting1: '還記得在蜜月灣，你曾經坐下來，讓海浪把心裡的聲音帶出來嗎？那一步其實很不簡單。接下來的路上，我會陪你在蘭陽的風雨裡，練習穩住自己的呼吸。',
        heroGreeting2: '你已經在蜜月灣靜坐過，也走過蘭陽的細雨。比起剛出發的自己，現在的你更懂得怎麼和情緒一起走路了。下一站，我們一起去情人灣，看一場屬於你的日出。',
        heroGreeting3: '三段海岸你都走過了：蜜月灣的呢喃、蘭陽的風雨、情人灣的日出。以後每次再來到這條線，只要閉上眼，你都能想起自己曾經走過的那份勇氣。我還會在這裡，等你下一次想出發的時候。',
        heroGreetingDefault: '你已經在這條蘭陽海岸留下腳印了。無論現在走到第幾關，都可以花一點時間回頭看看：一路上的你，其實一直在長出新的自己。',
        heroFeedbackWave: '親愛的旅人，你願意在蜜月灣坐下來，聽海浪、也聽自己的心，這已經是一種罕見的勇氣。之後無論心再怎麼起伏，都記得：你曾經給過自己這樣一段安靜的時間。下一步，我會陪你在蘭陽的細雨裡，練習在風雨中也站得穩。',
        heroFeedbackRain: '你剛剛在蘭陽的風雨裡，練習了如何和憂慮、疲累一起呼吸。這表示你不只是面對海岸的風景，也願意面對自己。等你準備好，我們一起去情人灣，看看當陽光慢慢升起時，你的心會長成什麼樣子。',
        heroFeedbackDawn: '恭喜你走完了這三段海岸。從蜜月灣的呢喃、到細雨中的沉澱，再到情人灣的日出，你一步一步親眼見證了自己的變化。這趟旅程不會因為完成就結束，只要你想起這些片刻，那份勇氣就會再次被喚醒，而我也會一直記得你走過的路。',
        heroFeedbackDefault: '你完成了一段不簡單的。或許現在你還說不清這段路改變了什麼，但沒關係，真正的變化會慢慢在日常裡浮現。我會記得你今天走過這裡。',
