        aboutSongDesc: '《蘭陽フェリー・ヒーロー旅》は「蘭陽フェリーヒーロー旅」のために作成されたテーマソングです。歌詞は蘭陽海岸沿いの旅を描き、孤独を経験することで自分を見つけるヒーローの旅を描いています。亀山島から砂丘、利澤から伝藝まで、各ステップは昨日と分離し、より良い自分に向かうプロセスです。',
        aboutSongDesc2: 'この音楽はミッション中に再生するのに適しており、海岸のヒーリング雰囲気を作り出し、内面成長の各段階を通じてあなたに付き添います。',
