        routeStep3Location: '📍 三敆水',
        routeStep3Desc: 'AIがあなたを三敆水一帯の砂丘でゆっくりと歩くよう導き、砂の上に残した一連の足跡を観察します。これらの足跡は、あなたが歩んできた過去の経験を表し、「足跡は最終的に風と砂で消える」という象徴でもあります。私たちの過去も再理解され、安らかに置かれることができるでしょうか？',
