        routeStep5Title: '⭐ 第五関：星空の下の祈願',
        routeStep5Location: '📍 東港榕樹公園',
        routeStep5Desc: '東港榕樹公園の夜、旅行者はハンモックに横たわり、星空を見上げることができます。AIがあなたに1分間の静かな瞑想を導き、その後あなたの願いや期待を書き留めます。',
        routeStep6Title: '🌾 第六関：風の中の声',
        routeStep6Location: '📍 五十二甲湿地',
        routeStep6Desc: '五十二甲湿地で、旅行者は自転車で小道を走り、田んぼの香りを楽しむことができます。AIがあなたに導きます：風の中の声を聞いていますか？この声はどのようにあなた自身の人生を連想させますか？',
