        routeStep8Title: '🌊 第八関：川の中の倒影',
        routeStep8Location: '📍 利澤沙丘海岸',
        routeStep8Desc: '利澤沙丘海岸の川辺で、旅行者はAIに導かれて自分の倒影を観察し、考えます：これは今の自分ですか、それとも過去の自分ですか？旅行者は自分の倒影を撮影し、感情を記録することができます。',
