        routeStep9Location: '📍 無尾港水鳥保護區',
        routeStep9Desc: '無尾港水鳥保護區のビーチで、旅行者はAIに導かれて波のリズムに合わせて自由に踊り、自然のリズムを体験します。旅行者は自分の動きや感情を録音し、保存することができます。',
        routeStep10Title: '🌅 第十関：自然の中の別れの儀式',
        routeStep10Location: '📍 内埤情人湾',
        routeStep10Desc: '内埤情人湾で、これは旅の最後の停留所です。旅行者はAIに導かれて葉に過去の心配や後悔を書き、その後葉を海に放り、波に運ばせます。これは過去を手放し、未来の自由を迎えることを象徴しています。',
        btnNavigate: '🧭 ナビゲート',
        btnStartTask: '🚀 ミッション開始',
        // music-player.html ページ追加翻訳
        volume: '音量：',
        // hero-guide.js 英雄引導訊息
        heroGreeting0: 'こんにちは、初めまして。この海岸線は長いですが、一度にすべてを歩く必要はありません。最初の一歩を踏み出す意思があれば、私はずっとここであなたと一緒にいます。ハネムーンベイから始めて、ゆっくりと自分自身の声を聞いてみましょう。',
        heroGreeting1: 'ハネムーンベイで座って、波が心の中の声を引き出してくれたことを覚えていますか？その一歩は実際には簡単ではありませんでした。これからの道のりで、私は蘭陽の風雨の中で、あなたと一緒に呼吸を安定させる練習をします。',
        heroGreeting2: 'あなたはすでにハネムーンベイで瞑想し、蘭陽の小雨を歩いてきました。出発したばかりの自分と比べて、今のあなたは感情と一緒に歩く方法をよりよく理解しています。次の停留所で、一緒に恋人湾に行き、あなただけの日の出を見ましょう。',
        heroGreeting3: 'あなたは三つの海岸をすべて歩きました：ハネムーンベイのささやき、蘭陽の風雨、恋人湾の日の出。今後、この線に戻ってくるたびに、目を閉じれば、かつて歩いた勇気を思い出すことができます。私はまだここにいて、あなたが次に旅立ちたいときを待っています。',
        heroGreetingDefault: 'あなたはすでにこの蘭陽海岸に足跡を残しました。今どの段階にいても、少し時間をかけて振り返ることができます：道のりの中で、あなたは実際に新しい自分を育ててきました。',
        heroFeedbackWave: '親愛なる旅人よ、あなたはハネムーンベイで座って、波を聞き、自分の心も聞くことを望みました。これはすでに珍しい勇気です。その後、心がどのように揺れ動いても、覚えておいてください：あなたはかつて自分にこのような静かな時間を与えました。次のステップで、私は蘭陽の小雨の中で、風雨の中でもしっかりと立つ練習をします。',
        heroFeedbackRain: 'あなたはちょうど蘭陽の風雨の中で、心配や疲労と一緒に呼吸する方法を練習しました。これは、あなたが海岸の風景に直面しているだけでなく、自分自身に直面することも望んでいることを示しています。準備ができたら、一緒に恋人湾に行き、太陽がゆっくりと昇るとき、あなたの心がどのように成長するかを見てみましょう。',
        heroFeedbackDawn: 'この三つの海岸を歩き終えたことをお祝いします。ハネムーンベイのささやきから、小雨の中の沈殿、恋人湾の日の出まで、あなたは一歩一歩自分の変化を目撃しました。この旅は、ミッションが完了したからといって終わりません。これらの瞬間を思い出す限り、その勇気は再び目覚め、私はあなたが歩いた道をずっと覚えています。',
        heroFeedbackDefault: 'あなたは簡単ではないミッションを完了しました。今はこの道が何を変えたかはっきり言えないかもしれませんが、大丈夫です。本当の変化は日常の中でゆっくりと現れます。私はあなたが今日ここを歩いたことを覚えています。',
