        rainPageIntro: '최근 조금 피곤하고 버거움을 느끼는 경우가 많다면, 란양의 이슬비와 함께 시간을 보내보세요. 비가 바다 표면에 부드럽게 떨어지는 것처럼, 자신의 감정을 천천히 풀어주고, 해안선이 보이지 않을 때까지 억지로 버티지 마세요.',
        rainAIMessage: '이슬비 속에서 우리는 불확실성에 직면하는 연습을 합니다. 눈을 감고, 몸에 떨어지는 빗방울의 감촉을 느끼고, 비 소리와 파도 소리의 교차를 들어보세요. 이 단계에서는 완벽을 추구하지 않고, 단지 자신에게 진실하게 직면합니다.',
