        // 第三關：沙丘上的腳印（三敆水）
        dawnTitle: '🏜 모래언덕의 발자국',
        dawnSubtitle: '📍 삼敆수・3단계',
        dawnPageTitle: '3단계｜모래언덕의 발자국（삼敆수）',
        dawnPageIntro: 'AI는 당신을 삼敆수 일대의 모래언덕에서 천천히 걷도록 안내하고, 모래 위에 남긴 일련의 발자국을 관찰하게 합니다. 이 발자국들은 당신이 걸어온 과거 경험을 나타내며, "발자국은 결국 바람과 모래에 의해 지워질 것"이라는 상징이기도 합니다. 우리의 과거도 재이해되고 배치될 수 있을까요? 여행자는 자신의 발자국을 촬영하고 AI에 감정을 기록할 수 있습니다.',
        dawnAIMessage: '준비되셨나요? "음성 가이드 시작"을 클릭하여 이 내면의 여정을 시작하세요.',
        voiceGuideDawn: '모래언덕을 따라 천천히 앞으로 걸어가며, 발바닥이 모래 위에서 느끼는 무게와 질감을 느껴보세요. 한 걸음 한 걸음, 자신이 남긴 발자국을 내려다보며 자문하세요: 이 발자국들은 당신의 어떤 과거를 나타내나요? 마음 속에 계속 가지고 있지만 아직 제대로 말하지 못한 이야기는 무엇인가요?',
        dawnUserResponse: '공유해주세요: 이 발자국들은 당신의 어떤 과거를 나타내나요? 마음 속에 계속 가지고 있지만 아직 제대로 말하지 못한 이야기는 무엇인가요?',
        dawnAIFeedbackCalm: '친애하는 여행자여, 당신은 내면의 평온을 찾았습니다. 모래언덕의 발자국이 바람과 모래에 의해 천천히 지워지듯이, 당신의 과거도 시간 속에서 천천히 가라앉을 것입니다. 중요한 것은 당신이 이미 과거와 화해하는 방법을 배웠다는 것입니다.',
        dawnAIFeedbackWorried: '친애하는 여행자여, 당신의 걱정을 들었습니다. 발자국이 사라지더라도 의미는 남아있듯이, 당신의 과거는 지나가더라도 거기서 배운 지혜가 당신을 계속 앞으로 나아가게 할 것입니다.',
        dawnAIFeedbackThinking: '친애하는 여행자여, 생각하는 것은 좋은 시작입니다. 모래언덕과 바람 모래와 함께, 아직 말하지 못한 이야기들을 천천히 정리하세요. 당신은 자신의 방향을 찾고 있으며, 이것 자체가 성장의 증거입니다.',
